import{_ as o,o as d,c as a,a3 as t}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Tenant API v1 — Knowledge Base","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Knowledge Base | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-knowledge-base"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Knowledge Base | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-knowledge-base"}]]},"headers":[],"relativePath":"api/tenant-v1-knowledge-base.md","filePath":"api/tenant-v1-knowledge-base.md","lastUpdated":1786755518000}'),c={name:"api/tenant-v1-knowledge-base.md"};function s(i,e,n,l,r,g){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="tenant-api-v1-—-knowledge-base" tabindex="-1">Tenant API v1 — Knowledge Base <a class="header-anchor" href="#tenant-api-v1-—-knowledge-base" aria-label="Permalink to &quot;Tenant API v1 — Knowledge Base&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:knowledge-base</code>.</p><p>All listed routes also require the stated <code>knowledge-base.*</code> Spatie permission.</p><p>Absolute datetimes serialize as UTC ISO-8601 (<code>...Z</code>). <code>published_at</code> is stored/cast as <code>UtcDateTime</code>.</p><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><h3 id="get-knowledge-base-stats" tabindex="-1">GET <code>/knowledge-base/stats</code> <a class="header-anchor" href="#get-knowledge-base-stats" aria-label="Permalink to &quot;GET `/knowledge-base/stats`&quot;">​</a></h3><p>Permission: <code>knowledge-base.view</code></p><p>KPI counts (<code>total</code>, <code>draft</code>, <code>published</code>, <code>archived</code>) over the same visibility/filter set as list (view-only actors count published only).</p><h3 id="get-knowledge-base" tabindex="-1">GET <code>/knowledge-base</code> <a class="header-anchor" href="#get-knowledge-base" aria-label="Permalink to &quot;GET `/knowledge-base`&quot;">​</a></h3><p>Permission: <code>knowledge-base.view</code></p><p>Query:</p><ul><li><code>search</code> — title, excerpt, body</li><li><code>category_id</code></li><li><code>sort</code> — <code>title</code> | <code>status</code> | <code>published_at</code> | <code>created_at</code> | <code>updated_at</code> (default <code>created_at</code>)</li><li><code>direction</code> — <code>asc</code> | <code>desc</code></li><li><code>page</code>, <code>per_page</code></li></ul><p>Editors with <code>knowledge-base.update</code> may also pass:</p><ul><li><code>status</code> — <code>draft</code> | <code>published</code> | <code>archived</code></li><li><code>trashed</code> — <code>only</code> | <code>true</code> | <code>with</code></li></ul><p>View-only: published audience only (no draft/archived/trash).</p><h3 id="post-knowledge-base" tabindex="-1">POST <code>/knowledge-base</code> <a class="header-anchor" href="#post-knowledge-base" aria-label="Permalink to &quot;POST `/knowledge-base`&quot;">​</a></h3><p>Permission: <code>knowledge-base.create</code></p><p>Body: <code>title</code> (required), <code>body</code> (required TipTap HTML); optional <code>slug</code>, <code>excerpt</code>, <code>category_id</code>, <code>status</code> (default <code>draft</code>).</p><p>Publishing on create sets <code>published_at</code>.</p><h3 id="get-knowledge-base-id" tabindex="-1">GET <code>/knowledge-base/{id}</code> <a class="header-anchor" href="#get-knowledge-base-id" aria-label="Permalink to &quot;GET `/knowledge-base/{id}`&quot;">​</a></h3><p>Permission: <code>knowledge-base.view</code> (policy enforces published-only for non-editors). Soft-deleted rows return not found on show.</p><p>Includes category, creator, notes, and activities when loaded.</p><h3 id="put-knowledge-base-id" tabindex="-1">PUT <code>/knowledge-base/{id}</code> <a class="header-anchor" href="#put-knowledge-base-id" aria-label="Permalink to &quot;PUT `/knowledge-base/{id}`&quot;">​</a></h3><p>Permission: <code>knowledge-base.update</code></p><p>Body (partial): <code>title</code>, <code>slug</code>, <code>excerpt</code>, <code>body</code>, <code>category_id</code>, <code>status</code>.</p><p>Transition into <code>published</code> sets <code>published_at</code> when missing; transition to <code>draft</code> clears <code>published_at</code>. No publish notification fan-out in v1.</p><h3 id="delete-knowledge-base-id" tabindex="-1">DELETE <code>/knowledge-base/{id}</code> <a class="header-anchor" href="#delete-knowledge-base-id" aria-label="Permalink to &quot;DELETE `/knowledge-base/{id}`&quot;">​</a></h3><p>Permission: <code>knowledge-base.delete</code> — soft delete.</p><h3 id="post-knowledge-base-id-restore" tabindex="-1">POST <code>/knowledge-base/{id}/restore</code> <a class="header-anchor" href="#post-knowledge-base-id-restore" aria-label="Permalink to &quot;POST `/knowledge-base/{id}/restore`&quot;">​</a></h3><p>Permission: <code>knowledge-base.restore</code></p><h3 id="delete-knowledge-base-id-force" tabindex="-1">DELETE <code>/knowledge-base/{id}/force</code> <a class="header-anchor" href="#delete-knowledge-base-id-force" aria-label="Permalink to &quot;DELETE `/knowledge-base/{id}/force`&quot;">​</a></h3><p>Permission: <code>knowledge-base.force.delete</code> — article must already be soft-deleted.</p><h3 id="post-knowledge-base-id-notes" tabindex="-1">POST <code>/knowledge-base/{id}/notes</code> <a class="header-anchor" href="#post-knowledge-base-id-notes" aria-label="Permalink to &quot;POST `/knowledge-base/{id}/notes`&quot;">​</a></h3><p>Permission: <code>knowledge-base.update</code></p><p>Body: <code>{ &quot;body&quot;: &quot;string&quot; }</code></p><h3 id="get-knowledge-base-id-timeline" tabindex="-1">GET <code>/knowledge-base/{id}/timeline</code> <a class="header-anchor" href="#get-knowledge-base-id-timeline" aria-label="Permalink to &quot;GET `/knowledge-base/{id}/timeline`&quot;">​</a></h3><p>Permission: <code>knowledge-base.view</code></p><p>Domain activity entries (<code>type</code>, <code>description</code>, <code>properties</code>, actor).</p><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Same module gate and <code>knowledge-base.*</code> permissions.</p><h3 id="get-knowledge-base-categories" tabindex="-1">GET <code>/knowledge-base-categories</code> <a class="header-anchor" href="#get-knowledge-base-categories" aria-label="Permalink to &quot;GET `/knowledge-base-categories`&quot;">​</a></h3><p>Permission: <code>knowledge-base.view</code> — ordered by <code>sort_order</code>, then name.</p><h3 id="post-knowledge-base-categories" tabindex="-1">POST <code>/knowledge-base-categories</code> <a class="header-anchor" href="#post-knowledge-base-categories" aria-label="Permalink to &quot;POST `/knowledge-base-categories`&quot;">​</a></h3><p>Permission: <code>knowledge-base.create</code></p><p>Body: <code>name</code> (required); optional <code>slug</code>, <code>sort_order</code>, <code>is_active</code>.</p><h3 id="get-put-delete-knowledge-base-categories-id" tabindex="-1">GET|PUT|DELETE <code>/knowledge-base-categories/{id}</code> <a class="header-anchor" href="#get-put-delete-knowledge-base-categories-id" aria-label="Permalink to &quot;GET|PUT|DELETE `/knowledge-base-categories/{id}`&quot;">​</a></h3><p>View (<code>knowledge-base.view</code>), update (<code>update</code>), soft-delete (<code>delete</code>).</p><p>Soft delete fails with validation if any articles still reference the category.</p><h3 id="post-knowledge-base-categories-id-restore" tabindex="-1">POST <code>/knowledge-base-categories/{id}/restore</code> <a class="header-anchor" href="#post-knowledge-base-categories-id-restore" aria-label="Permalink to &quot;POST `/knowledge-base-categories/{id}/restore`&quot;">​</a></h3><p>Permission: <code>knowledge-base.restore</code></p><h3 id="delete-knowledge-base-categories-id-force" tabindex="-1">DELETE <code>/knowledge-base-categories/{id}/force</code> <a class="header-anchor" href="#delete-knowledge-base-categories-id-force" aria-label="Permalink to &quot;DELETE `/knowledge-base-categories/{id}/force`&quot;">​</a></h3><p>Permission: <code>knowledge-base.force.delete</code> — blocked while any articles (including soft-deleted) still reference the category.</p>',53)])])}const h=o(c,[["render",s]]);export{b as __pageData,h as default};
